(() => {
  const g = __rhf.game;
  g.state.settings.autoQuality = false;
  g.setQuality('low');
  g.bears.directorT = 1e9;
  g.env.timeScale = 0;
  g.env.setTime(14);
  const w = g.env.weather;
  w.rain = w.rainTarget = 0;
  w.cloud = w.cloudTarget = 0.2;
  w.timer = 1e9;
  g.hud.firstShown = -1000;
  g.hud.hint('', 0);
  __rhf.god(true);
  // the slow test renderer never finishes a style transition before a
  // picture: show the messages where they end up
  const st = document.createElement('style');
  st.textContent = '#toasts, #banner { transition: none !important; }';
  document.head.appendChild(st);
  window.__until = async (fn, ms = 240000) => {
    const t0 = performance.now();
    while (performance.now() - t0 < ms) {
      const r = fn();
      if (r) return r;
      await new Promise((q) => setTimeout(q, 200));
    }
    return null;
  };
  // stand somewhere and face something, with the ground detail finished
  window.__stand = (x, z, lookX, lookZ, pitch = 0) => {
    const P = g.player;
    P.place(x, z, Math.atan2(-(lookX - x), -(lookZ - z)));
    P.pitch = pitch;
    __rhf.settle();
  };
  window.__ia = () => (g.interaction ? g.interaction.label : '-') + ' / ' + (g.interaction2 ? g.interaction2.label : '-');
  return 'set up; secret parts: ' + Object.keys(g.props.secret).join(', ') + '; flags ' + JSON.stringify(g.state.flags);
})()

(() => {
  const g = __rhf.game;
  const T = { x: -1115, z: -307 };
  const ty = g.world.heightAt(T.x, T.z);
  const inp = g.input;
  const set = (code, on) => (on ? inp.keys.add(code) : inp.keys.delete(code));
  window.__pilot = () => {
    const G = g.glider;
    const dx = T.x - G.pos.x;
    const dz = T.z - G.pos.z;
    const d = Math.hypot(dx, dz);
    const want = Math.atan2(-dx, -dz);
    const diff = Math.atan2(Math.sin(want - G.heading), Math.cos(want - G.heading));
    const over = G.pos.y - ty;
    let left = diff > 0.03;
    let right = diff < -0.03;
    let dive = over - d / 8 > 3;
    if (d < 25 && over > 6) {
      left = true;
      right = false;
      dive = true;
    }
    set('KeyA', left);
    set('KeyD', right);
    set('KeyW', dive);
  };
  window.__pilotOff = () => { for (const k of ['KeyA', 'KeyD', 'KeyW']) set(k, false); };
  return 'autopilot ready';
})()

(() => {
    const g = __rhf.game;
    g.state.flags.glider = true;
    const c = g.props.secret.cache;
    __stand(c.x + 1, c.z + 3, c.x + 1, c.z + 100, -0.12);
    return 'at the edge with the glider: actions ' + __ia();
  })()

(() => {
    const g = __rhf.game;
    __rhf.press('interact');
    window.__flight = { t0: g.time };
    window.__auto = setInterval(() => { if (g.player.mode === 'glide') __pilot(); }, 30);
    return 'pressed GLIDE';
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.player.mode === 'glide' && g.time - __flight.t0 > 3.2, 240000);
    const G = g.glider;
    return 'in the air ' + (g.time - __flight.t0).toFixed(1) + ' s (game loop): height ' + G.height().toFixed(0) + ' m, ' + (G.speed * 3.6).toFixed(0) + ' km/h, sink ' + G.sink.toFixed(2) + ' m/s; HUD "' + document.getElementById('glide').textContent.replace(/\s+/g, ' ').trim() + '"; cast button hidden ' + document.getElementById('btn-primary').hidden + ', hands on the brakes ' + g.viewmodel.glideRig.visible;
  })()

(() => {
    const g = __rhf.game;
    clearInterval(__auto);
    g.player.pitch = 0.95;
    // hold the view up for the picture
    return 'looking up at the wing';
  })()

(() => {
    const g = __rhf.game;
    const G = g.glider;
    const P = g.player;
    P.pitch = -0.2;
    // fast-forward: the same Glider.update the game loop calls, 30 steps a second
    const track = [];
    let n = 0;
    while (P.mode === 'glide' && n < 30 * 120) {
      __pilot();
      G.update(1 / 30, g.input);
      n++;
      if (n % 90 === 0) track.push('(' + G.pos.x.toFixed(0) + ',' + G.pos.z.toFixed(0) + ') ' + G.pos.y.toFixed(0) + ' m');
    }
    __pilotOff();
    const k = g.props.secret.keySpot;
    const t = g.time - __flight.t0 + n / 30;
    window.__landing = { x: P.pos.x, z: P.pos.z, y: P.pos.y };
    return 'landed after ' + t.toFixed(1) + ' s at (' + P.pos.x.toFixed(1) + ', ' + P.pos.z.toFixed(1) + ') y ' + P.pos.y.toFixed(1) + ', ' + Math.hypot(P.pos.x - k.x, P.pos.z - k.z).toFixed(1) + ' m from the key; mode ' + P.mode + ', canopy ' + G.canopy.visible + '; track every 3 s: ' + track.join(' > ');
  })()

(() => {
    const g = __rhf.game;
    const G = g.props.secret;
    const k = G.keySpot;
    // look round at the grotto from where you came down
    const P = g.player;
    P.yaw = Math.atan2(-(k.x - P.pos.x), -(k.z - P.pos.z));
    P.pitch = -0.15;
    __rhf.settle();
    return 'facing the grotto';
  })()

